import {rangePlayback,table} from './topic-tools.js';
import {visionPatchLoss,visionAgreement,visionSIGReg,visionProjectedLaw} from './vision-model.js';
const f=x=>Number(x.toFixed(4)).toString();
const scrollTable=(caption,heads,rows)=>table(caption,heads,rows).replace('class="dense-table-wrap"','class="dense-table-wrap" tabindex="0" role="region" aria-label="'+caption+'"');
export const visionPatchTargets=[[.7,.2,.1],[.1,.6,.3],[.2,.3,.5],[0,0,1]];
export const visionPatchMask=[true,false,true,false];
export function visionMaskBody(scope='masked',visibleLogit=10,step=0){
 if(!Number.isInteger(visibleLogit)||visibleLogit<0||visibleLogit>30||!Number.isInteger(step)||step<0||step>4)throw new RangeError('Invalid patch display state');
 const z=[[2,-1,0],[visibleLogit/10,1,3],[-2,2,0],[1,1,1]],m=visionPatchLoss(z,visionPatchTargets,visionPatchMask,scope);
 const captions=['Assign four matching patch positions. Mask student positions0 and2; the teacher sees all four.','Produce stopped teacher prototype probabilities. The assigned rows remain fixed in this demonstration.','Compute student prototype probabilities from the masked-view context. Visible patch1 has an adjustable first logit.','Select loss positions: '+(scope==='all'?'all four, including visible patches.':'only masked positions0 and2.'),'Differentiate the selected mean cross-entropy through student logits. The stopped teacher receives no loss gradient.'];
 const color=i=>visionPatchMask[i]?'#d99ab4':'#bad6fa';
 const svg='<svg viewBox="0 0 560 220" role="img" aria-label="Four teacher patch targets above four student patch predictions; masked input and loss selection are separate"><text x="12" y="22">Unmasked teacher · stopped targets</text>'+m.rows.map((r,i)=>'<rect x="'+(12+i*136)+'" y="35" width="122" height="42" rx="5" fill="#bad6fa18" stroke="#bad6fa"/><text x="'+(19+i*136)+'" y="61">'+i+': '+r.teacher.map(f).join('/')+'</text><line x1="'+(73+i*136)+'" y1="80" x2="'+(73+i*136)+'" y2="111" stroke="'+(step>=3&&r.selected?color(i):'#716077')+'" stroke-width="'+(step>=3&&r.selected?3:1)+'"'+(r.selected?'':' stroke-dasharray="4 4"')+'/><rect x="'+(12+i*136)+'" y="118" width="122" height="50" rx="5" fill="'+(visionPatchMask[i]?'#88425835':'#bad6fa18')+'" stroke="'+color(i)+'"/><text x="'+(19+i*136)+'" y="139">'+i+': '+(visionPatchMask[i]?'masked':'visible')+'</text><text x="'+(19+i*136)+'" y="156">'+(step>=3?(r.selected?'direct loss':'no direct loss'):'input status')+'</text>').join('')+'<text x="12" y="201">Student · masked input; contextual predictions still exist at all positions</text></svg>';
 return '<p data-vision-mask-result>Step='+step+'/4. '+captions[step]+'</p><div class="vision-plot" tabindex="0" role="region" aria-label="Teacher and student patch paths">'+svg+'</div>'+scrollTable('Prototype targets, predictions and direct gradients',['Patch / input','Teacher q','Student p','CE if selected','Direct logit gradient'],m.rows.map((r,i)=>[i+' / '+(r.masked?'masked':'visible'),r.teacher.map(f).join(' / '),r.probabilities.map(f).join(' / '),r.selected?f(r.loss):'excluded',m.gradient[i].map(f).join(' / ')]))+'<p data-vision-mask-numbers>Selected='+m.denominator+'; mean CE='+f(m.loss)+'; visible patch1 first-logit gradient='+f(m.gradient[1][0])+'.</p><p>Assigned probabilities and logits, temperature1; no image model is run. Changing the visible logit leaves the masked-only loss unchanged here because other logits are held fixed. In a transformer, visible inputs can still receive indirect gradients through predictions at masked positions. Zero direct logit gradient does not mean zero encoder gradient.</p>';
}
export function visionAgreementBody(errorPercent=50,separationPercent=100){
 for(const x of [errorPercent,separationPercent])if(!Number.isInteger(x)||x<0||x>100)throw new RangeError('Invalid agreement display parameter');
 const d=errorPercent/100,s=separationPercent/100,centers=[-1.5,-.5,.5,1.5].map(x=>x*s),views=[-d,d,2*d].map(offset=>centers.map(c=>[c+offset])),m=visionAgreement(views,2);
 const regularizer=views.reduce((a,view)=>a+visionSIGReg(view,[[1]],{scaled:false}).loss,0)/3;
 const x=v=>280+v*65,rows=views.map((view,i)=>view.map((row,n)=>'<circle cx="'+x(row[0])+'" cy="'+(40+i*48)+'" r="6" fill="'+(i<2?'#bad6fa':'#d99ab4')+'"/><text x="'+(x(row[0])+8)+'" y="'+(44+i*48)+'">'+n+'</text>').join(''));
 const svg='<svg viewBox="0 0 560 235" role="img" aria-label="Four image identities in two global views and one local view on a shared scalar embedding axis"><text x="8" y="17">Same image IDs0–3 across each row</text>'+['Global0','Global1','Local'].map((label,i)=>'<text x="8" y="'+(44+i*48)+'">'+label+'</text>'+rows[i]).join('')+'<line x1="20" y1="192" x2="540" y2="192" stroke="#aa96b1"/>'+[-4,-2,0,2,4].map(t=>'<text x="'+x(t)+'" y="215">'+t+'</text>').join('')+'</svg>';
 return '<div class="vision-plot" tabindex="0" role="region" aria-label="Agreement and separation of scalar image embeddings">'+svg+'</div><p data-vision-agreement-result>Centered agreement='+f(m.centered)+'; global-view variance='+f(m.globalVariance)+'; pairwise global-to-all='+f(m.pairwise)+'. Between-image center variance='+f(1.25*s*s)+'; finite four-sample projected discrepancy='+f(regularizer)+'.</p><p>Each image has center c. Global views are c−d and c+d; the local view is c+2d. Thus centered MSE=2d², global variance=d², and pairwise MSE=3d². Separation changes the image centers, not within-image agreement. At error0 and separation0, every view of every image is constant: perfect agreement but collapsed representation.</p><p>The displayed regularizer is an unscaled, Gaussian-windowed positive-half ECF integral,17 knots on[0,3], averaged over three four-image views. It is finite-sample evidence, not a Gaussianity certificate or a measured training curve. No optimizer or learned trajectory is simulated.</p>';
}
export function visionProjectionBody(family='cross',degree=45){
 if(!Number.isInteger(degree))throw new RangeError('Use an integer display angle');const point=visionProjectedLaw(family,degree,1),a=point.direction;
 const support=family==='gaussian'?'<circle cx="105" cy="100" r="68" fill="#bad6fa15" stroke="#bad6fa"/><circle cx="105" cy="100" r="40" fill="none" stroke="#bad6fa66"/>':family==='cross'?'<path d="M30 175L180 25 M30 25L180 175" fill="none" stroke="#d99ab4" stroke-width="4"/>':family==='square'?[[50,45],[160,45],[50,155],[160,155]].map(([x,y])=>'<circle cx="'+x+'" cy="'+y+'" r="6" fill="#d99ab4"/>').join(''):'<circle cx="105" cy="100" r="7" fill="#d99ab4"/>';
 // The real CF can be negative. Reserve [-1,1], not only the Gaussian's [0,1] range.
 const curve=which=>Array.from({length:61},(_,i)=>{const t=i/20,m=visionProjectedLaw(family,degree,t),y=which==='target'?m.target:m.real;return (i?'L':'M')+(260+t*88)+' '+(120-y*75);}).join(' ');
 const figure='<svg viewBox="0 0 560 260" role="img" aria-label="A conceptual two-dimensional distribution and its exact projected population characteristic function"><text x="8" y="18">Joint geometry · conceptual</text>'+support+'<line x1="'+(105-a[0]*85)+'" y1="'+(100+a[1]*85)+'" x2="'+(105+a[0]*85)+'" y2="'+(100-a[1]*85)+'" stroke="#f1e5ec" stroke-width="2"/><text x="12" y="215">Direction='+degree+'°</text><text x="255" y="18">Real characteristic function</text><line x1="250" y1="120" x2="535" y2="120" stroke="#aa96b1"/>'+[1,0,-1].map(value=>'<text x="235" y="'+(124-value*75)+'">'+value+'</text>').join('')+'<path d="'+curve('target')+'" fill="none" stroke="#bad6fa" stroke-width="3"/><path d="'+curve('law')+'" fill="none" stroke="#d99ab4" stroke-width="2" stroke-dasharray="5 3"/>'+[0,1,2,3].map(t=>'<text x="'+(260+t*88)+'" y="218">'+t+'</text>').join('')+'<text x="255" y="244">t · blue Gaussian target / dashed law</text></svg>';
 let discrepancy=0;for(let i=0;i<16;i++){const l=visionProjectedLaw(family,degree,i*3/16),r=visionProjectedLaw(family,degree,(i+1)*3/16);discrepancy+=3/16*(Math.exp(-l.t*l.t/2)*l.error+Math.exp(-r.t*r.t/2)*r.error);}
 const definition=family==='cross'?'U is standard Gaussian; an independent fair sign R gives Z=(U,RU). The joint law lies on two diagonals.':family==='square'?'Z has four equally weighted corners(±1,±1). Its covariance is identity, but its marginals are not Gaussian.':family==='gaussian'?'Z is an isotropic standard Gaussian. Every unit projection is standard Gaussian.':'Z=(0,0) always. Every projection is constant and has characteristic function1.';
 return '<div class="vision-plot" tabindex="0" role="region" aria-label="Projection direction and characteristic-function comparison">'+figure+'</div><p data-vision-projection-result>Angle='+degree+'°. Projected variance='+point.variance+'; at t=1, law CF='+f(point.real)+', target CF='+f(point.target)+', squared gap='+f(point.error)+'. Population quadrature discrepancy='+f(discrepancy)+'.</p><p>'+definition+' The diagrams show geometry, not measured density or sampled points. The curves are exact population characteristic functions. Their imaginary parts are zero by symmetry. The integral uses17 trapezoid knots on[0,3] with a Gaussian window and positive-half doubling.</p><p>For the diagonal law, directions0° and90° match the Gaussian target at every frequency. At45°, the projection is a half constant/half Gaussian mixture: φ(t)=(1+exp(−t²))/2. All directions still have variance1. Rotating the direction detects a difference that checking coordinate means and variances misses. A finite collection of successful directions is not a full distributional proof.</p>';
}
export function visionScenes(){return {
 mask:'<figure class="topic-scene" data-vision-lab="mask"><h3>Separate input masking from loss selection</h3><label>Patch loss positions<select aria-label="Vision patch loss positions"><option value="masked">Masked patches only</option><option value="all">All patches</option></select></label><label>Visible patch1 first logit ×10<input type="range" aria-label="Vision visible patch logit" min="0" max="30" step="1" value="10"></label><label>Patch computation stage<input type="range" aria-label="Vision patch computation stage" min="0" max="4" step="1" value="0"></label><div class="dense-actions"><button data-play>Play</button><button data-reset>Replay</button></div><div data-body>'+visionMaskBody()+'</div><figcaption>Assigned four-patch cross-entropy. Direct supervision is a loss-position decision; the input mask remains unchanged in both modes.</figcaption></figure>',
 agreement:'<figure class="topic-scene" data-vision-lab="agreement"><h3>Agreement does not imply useful image separation</h3><label>Within-image offset (%)<input type="range" aria-label="Vision within image offset" min="0" max="100" step="1" value="50"></label><label>Between-image separation (%)<input type="range" aria-label="Vision image separation" min="0" max="100" step="1" value="100"></label><div data-body>'+visionAgreementBody()+'</div><figcaption>Original scalar counterexample. Change agreement and separation independently; these controls are not training time.</figcaption></figure>',
 projection:'<figure class="topic-scene" data-vision-lab="projection"><h3>Gaussian marginals can hide a non-Gaussian joint law</h3><label>Embedding law<select aria-label="Vision embedding law"><option value="cross">Gaussian-marginal diagonals</option><option value="gaussian">Isotropic Gaussian</option><option value="square">Four square corners</option><option value="collapsed">Constant collapse</option></select></label><label>Projection direction (degrees)<input type="range" aria-label="Vision projection direction" min="0" max="180" step="1" value="45"></label><div class="dense-actions"><button data-play>Play</button><button data-reset>Replay</button></div><div data-body>'+visionProjectionBody()+'</div><figcaption>Exact population projection example, inspired by LeJEPA’s diagonal counterexample. Optional motion rotates the test direction, not the encoder or training process.</figcaption></figure>'
};}
export function mountVisionScenes(article){
 const mask=article.querySelector('[data-vision-lab="mask"]');if(mask){const scope=mask.querySelector('select'),logit=mask.querySelector('[aria-label="Vision visible patch logit"]'),step=mask.querySelector('[aria-label="Vision patch computation stage"]');const draw=()=>{mask.querySelector('[data-body]').innerHTML=visionMaskBody(scope.value,Number(logit.value),Math.round(Number(step.value)));};const playback=rangePlayback(article,mask,draw,12000,step);scope.addEventListener('change',()=>{playback.stop();draw();});logit.addEventListener('input',()=>{playback.stop();draw();});}
 const agreement=article.querySelector('[data-vision-lab="agreement"]');if(agreement){const offset=agreement.querySelector('[aria-label="Vision within image offset"]'),separation=agreement.querySelector('[aria-label="Vision image separation"]'),draw=()=>{agreement.querySelector('[data-body]').innerHTML=visionAgreementBody(Number(offset.value),Number(separation.value));};for(const input of [offset,separation])input.addEventListener('input',draw);}
 const projection=article.querySelector('[data-vision-lab="projection"]');if(projection){const law=projection.querySelector('select'),angle=projection.querySelector('input'),draw=()=>{projection.querySelector('[data-body]').innerHTML=visionProjectionBody(law.value,Math.round(Number(angle.value)));};const playback=rangePlayback(article,projection,draw,22000,angle);law.addEventListener('change',()=>{playback.stop();draw();});}
}
